parameters.jsCode:
// Ergebnis der KI-Analyse + Regeln aus der Tabelle -> Tabellenzeile.
const p = $json.output;
const g = $('Bewertungsgrundlage bauen').item.json;
const konfig = g.konfig;
const norm = (s) => String(s ?? '').trim().toLowerCase();

// KI-Bewertung den Kriterien aus dem Tab „Bewertung“ zuordnen.
const bewertungen = konfig.kriterien.map((k) => {
  const b = (p.bewertung ?? []).find((x) => norm(x.kriterium) === norm(k.name)) ?? {};
  const gueltig = b.beurteilbar !== false && Number.isFinite(b.score) && b.score >= k.min && b.score <= k.max;
  return { ...k, score: gueltig ? b.score : null, begruendung: b.begruendung ?? 'Nicht bewertet.', zitat: b.zitat ?? '' };
});

// Gesamtscore in Prozent: jede Skala auf 0–100 % normiert, dann nach Gewicht gemittelt.
let summe = 0;
let gewichte = 0;
for (const b of bewertungen) {
  if (b.score === null || b.gewicht <= 0) continue;
  const anteil = b.max > b.min ? (b.score - b.min) / (b.max - b.min) : 1;
  summe += anteil * b.gewicht;
  gewichte += b.gewicht;
}
const vollstaendig = p.status === 'vollständig';
const gesamt = vollstaendig && gewichte > 0 ? Math.round((summe / gewichte) * 100) : null;

// Empfehlung nach festen Regeln (Schwellen aus dem Tab „Stellen“).
const mussNein = (p.muss_kriterien ?? []).filter((m) => m.erfuellt === 'nein');
const regeln = [];
let empfehlung;
if (!vollstaendig) {
  empfehlung = 'Prüfen';
  regeln.push('Gespräch ' + p.status + ' → Prüfen');
} else if (gesamt === null) {
  empfehlung = 'Prüfen';
  regeln.push('Kein Kriterium beurteilbar → Prüfen');
} else if (gesamt >= konfig.einladenAb) {
  empfehlung = 'Einladen';
  regeln.push('Gesamtscore ' + gesamt + ' % ≥ ' + konfig.einladenAb + ' % → Einladen');
} else if (gesamt < konfig.absageUnter) {
  empfehlung = 'Absage';
  regeln.push('Gesamtscore ' + gesamt + ' % < ' + konfig.absageUnter + ' % → Absage');
} else {
  empfehlung = 'Prüfen';
  regeln.push('Gesamtscore ' + gesamt + ' % zwischen ' + konfig.absageUnter + ' % und ' + konfig.einladenAb + ' % → Prüfen');
}
if (empfehlung === 'Einladen' && mussNein.length) {
  empfehlung = 'Prüfen';
  regeln.push('Muss-Kriterium nicht erfüllt (' + mussNein.map((m) => m.kriterium).join(', ') + ') → höchstens Prüfen');
}
if (empfehlung === 'Einladen' && p.schwerwiegende_red_flag) {
  empfehlung = 'Prüfen';
  regeln.push('Schwerwiegende Red Flag → höchstens Prüfen');
}

const liste = (arr) => (arr ?? []).map((x) => '• ' + x).join('\n');
const scoreText = (b) => (b.score === null ? '–' : b.score + '/' + b.max);
const ICON_MUSS = { ja: '✓', nein: '✗', unklar: '?' };
// Google Sheets erlaubt max. 50.000 Zeichen pro Zelle.
const kuerzen = (t) => (t && t.length > 49000 ? t.slice(0, 49000) + '\n[… gekürzt]' : t ?? '');

return { json: {
  'Call-ID': g.callId,
  'Datum': g.datum,
  'Stelle': g.stelle,
  'Name': p.name,
  'Dauer (Min)': g.dauerMin,
  'Gesprächsende': g.endedReason,
  'Vollständig': vollstaendig ? 'Ja' : 'Nein – ' + p.status,
  'Empfehlung': empfehlung,
  'Gesamtscore (%)': gesamt ?? '',
  'Scores': bewertungen.map((b) => b.name + ' ' + scoreText(b)).join(' · '),
  'Muss-Kriterien': (p.muss_kriterien ?? []).map((m) => (ICON_MUSS[m.erfuellt] ?? '?') + ' ' + m.kriterium + (m.erfuellt === 'ja' ? '' : ': ' + m.begruendung)).join('\n'),
  'Zusammenfassung': p.zusammenfassung,
  'Stärken': liste(p.staerken),
  'Schwächen / Red Flags': liste(p.schwaechen_red_flags),
  'Begründungen': bewertungen.map((b) => b.name + ' (' + scoreText(b) + '): ' + b.begruendung + (b.zitat ? ' „' + b.zitat + '“' : '')).join('\n')
    + '\n\nEmpfehlung: ' + regeln.join('; ') + '\nEinschätzung: ' + (p.einschaetzung ?? ''),
  'Gehaltsvorstellung': p.eckdaten?.gehaltsvorstellung ?? '',
  'Verfügbarkeit': p.eckdaten?.verfuegbarkeit ?? '',
  'Startdatum': p.eckdaten?.startdatum ?? '',
  'Offene Punkte': liste(p.offene_punkte),
  'Aufnahme': g.aufnahmeUrl,
  'Transkript': kuerzen(g.transkript),
  'Verarbeitet am': $now.setZone('Europe/Berlin').toFormat('dd.MM.yyyy HH:mm'),
} };

// Slack Block Kit: rein informativ, ohne Buttons (REQ-5.2, REQ-5.3).
const r = $('Protokoll aufbereiten').item.json;
const SHEET_URL = 'https://docs.google.com/spreadsheets/d/1Wx4lcM86H-tjIn-QIrrxWEWlgSUsUUfNn2TZr_n4CIA/edit#gid=0';
const link = $json.row_number ? SHEET_URL + '&range=A' + $json.row_number : SHEET_URL;

// Slack mrkdwn verlangt escapte Sonderzeichen.
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Slack-Limits: 3000 Zeichen pro Textblock, 2000 pro Feld.
const kurz = (t, max) => (t.length > max ? t.slice(0, max - 2) + ' …' : t);

// Unvollständige Gespräche und fehlende Einwilligung werden nicht normal bewertet (REQ-4.7).
const ICON = { Einladen: '🟢', 'Prüfen': '🟡', Absage: '🔴' };
let titel;
if (r['Vollständig'] === 'Ja') {
  titel = (ICON[r.Empfehlung] ?? '⚪') + ' ' + r.Empfehlung + ' – ' + r.Name;
} else if (r['Vollständig'].includes('keine Einwilligung')) {
  titel = '⚪ Keine Einwilligung – ' + r.Name;
} else {
  titel = '⚪ ' + r.Empfehlung + ' (unvollständig) – ' + r.Name;
}
const gesamt = r['Gesamtscore (%)'] === '' ? '–' : r['Gesamtscore (%)'] + ' %';
const mussOffen = String(r['Muss-Kriterien'] ?? '').split('\n').filter((z) => z && !z.startsWith('✓'));

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: kurz(titel, 150), emoji: true } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*Stelle*\n' + esc(r.Stelle) },
    { type: 'mrkdwn', text: '*Gesamtscore*\n' + gesamt },
    { type: 'mrkdwn', text: '*Datum*\n' + esc(r.Datum) },
    { type: 'mrkdwn', text: '*Dauer*\n' + String(r['Dauer (Min)']).replace('.', ',') + ' Min.' },
  ] },
  { type: 'section', text: { type: 'mrkdwn', text: kurz('*Zusammenfassung*\n' + esc(r.Zusammenfassung), 3000) } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: kurz('*Stärken*\n' + (esc(r['Stärken']) || '–'), 2000) },
    { type: 'mrkdwn', text: kurz('*Schwächen / Red Flags*\n' + (esc(r['Schwächen / Red Flags']) || '–'), 2000) },
  ] },
  { type: 'section', text: { type: 'mrkdwn', text: kurz('*Scores*  ' + esc(r.Scores), 3000) } },
];
if (mussOffen.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: kurz('*Muss-Kriterien prüfen*\n' + esc(mussOffen.join('\n')), 3000) } });
}
blocks.push(
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*Gehaltsvorstellung*\n' + (esc(r.Gehaltsvorstellung) || '–') },
    { type: 'mrkdwn', text: '*Startdatum*\n' + (esc(r.Startdatum) || '–') },
  ] },
  { type: 'divider' },
  { type: 'context', elements: [{ type: 'mrkdwn', text: '<' + link + '|Vollständiges Protokoll in Google Sheets>  ·  Empfehlung nach den Regeln im Tab „Stellen“ – die Entscheidung trifft HR.' }] },
);

return { json: { slackBlocks: JSON.stringify({ blocks }), slackText: titel } };
